    return JSON.stringify(rawData, null, 2);

} catch (error) {
    // 捕捉節點名稱錯誤或執行異常
    return `❌ 錯誤：無法獲取 "StreamerEventLog" 資料。請檢查節點名稱是否正確。原因：${error.message}`;
}

