DECLARE start_timestamp TIMESTAMP;
DECLARE end_timestamp TIMESTAMP;

SET end_timestamp = TIMESTAMP_ADD(TIMESTAMP_SECONDS(1769965459), INTERVAL 5 MINUTE);
SET start_timestamp = TIMESTAMP_SUB(TIMESTAMP_SECONDS(1769959969), INTERVAL 5 MINUTE);

/* 第一步：先把 JSON 裡面的 title 拔出來變成一個實體欄位 */
WITH ProcessedLogs AS (
  SELECT
    DATETIME(timestamp, "Asia/Taipei") as UTCp8,
    Type,
    JSON_EXTRACT_SCALAR(Log, '$.time') as LocalTime,
    JSON_EXTRACT_SCALAR(Log, '$.title') AS title, -- 提取為 title
    Log,
    triggerUserID,
    deviceType,
    ip,
    region,
    deviceID,
    version,
    timestamp
  FROM
    `media17-1119.BackendEvent.IstStreamerEventLog`
  WHERE
    timestamp BETWEEN start_timestamp AND end_timestamp
    AND CAST(triggerUserID AS STRING) = "9a9a3b51-2129-4ae7-a5e8-b0449825cb4d"
)

/* 第二步：現在這裡可以自由使用 title 這個欄位了 */
SELECT * FROM ProcessedLogs
WHERE  {{ $fromAI('query', '例如 title = "Poor CDN Connection"') }} 
ORDER BY
  UTCp8 ASC;
